function main(): void {
  const a = new Error("plain", { cause: "x" }) as any;
  a.stack = "Error: plain";
  console.log(a);
  const inner = new RangeError("deep") as any;
  inner.stack = "RangeError: deep";
  const b = new Error("wrap", { cause: inner }) as any;
  b.stack = "Error: wrap";
  console.log(b);
  console.log([b]);
}
